select t.*, (select pc.check_date from prj_check pc where pc.check_id = t.last_check_id) last_check_date, (select scvb.meaning from sys_code_b scb, sys_code_value_b scvb,prj_check pc where scb.code_id = scvb.code_id and scvb.enabled_flag = 'Y' and scb.code = 'CHECK_TYPE' and scvb.value = pc.CHECK_TYPE and pc.check_id = t.last_check_id) last_check_type, (select pc.CONCLUSION from prj_check pc where pc.check_id = t.last_check_id) last_conclusion, (select pc.next_check_matter from prj_check pc where pc.check_id = t.last_check_id) check_matter, (select pc.focus_matter from prj_check pc where pc.check_id = t.last_check_id) last_focus_matter, (select pc.correct_situation from prj_check pc where pc.check_id = t.last_check_id) last_correct_situation, (select pc.FIVE_CLASSIFICATION_RESULT from prj_check pc where pc.check_id = t.last_check_id) last_five_result, (select scvb.meaning from sys_code_b scb, sys_code_value_b scvb,prj_check pc where pc.check_id = t.last_check_id and scb.code_id = scvb.code_id and scvb.enabled_flag = 'Y' and scb.code = 'FIVE_CLASSIFICATION_RESULT' and scvb.value = pc.FIVE_CLASSIFICATION_RESULT) last_five_result_n from (SELECT c.created_by, p.check_date, p.contract_id, P.process_instance_id, p.CONCLUSION, p.EXIST_QUESTION, p.USE_MEASURE, p.POLICY_FINANCE_SITUATION, p.PRODUCT_MATERIAL_SITUATION, p.PRODUCT_ENVIRONMENT_SITUATION, p.office_environment_situation, p.product_time_situation, p.EXPAND_INVEST, p.OTHER_SITUATION, p.CORRECT_SITUATION, p.FIVE_CLASSIFICATION_RESULT, (select scvb.meaning from sys_code_b scb, sys_code_value_b scvb where scb.code_id = scvb.code_id and scvb.enabled_flag = 'Y' and scb.code = 'FIVE_CLASSIFICATION_RESULT' and scvb.value = p.FIVE_CLASSIFICATION_RESULT) FIVE_CLASSIFICATION_RESULT_N, p.PRODUCT_CONCLUSION, (select scvb.meaning from sys_code_b scb, sys_code_value_b scvb where scb.code_id = scvb.code_id and scvb.enabled_flag = 'Y' and scb.code = 'FIVE_CLASSIFICATION_RESULT' and scvb.value = p.PRODUCT_CONCLUSION) PRODUCT_CONCLUSION_N, p.check_type, (select scvb.meaning from sys_code_b scb, sys_code_value_b scvb where scb.code_id = scvb.code_id and scvb.enabled_flag = 'Y' and scb.code = 'CHECK_TYPE' and scvb.value = p.CHECK_TYPE) CHECK_TYPE_N, p.check_id, p.approve_suggest, (select pp.plan_number from prj_check_plan pp where pp.plan_id=p.plan_id) PLAN_ID_N, ( SELECT scvb.meaning AS value_name FROM sys_code_value_b scvb, sys_code_b scb WHERE scb.CODE = 'HLS.WORK_FLOW_STATUS' AND scb.code_id = scvb.code_id AND scvb.enabled_flag = 'Y' AND scvb.VALUE= p.approve_suggest ) approve_suggest_n, c.tenant_id bp_id,
(SELECT b.bp_name FROM hls_bp_master b WHERE c.tenant_id = b.bp_id) AS bp_name, (select cb.bp_id from con_contract_bp cb where cb.contract_id = con.contract_id and cb.bp_category = 'GUARANTOR') guarantor_id, (select m.bp_name from con_contract_bp cb, hls_bp_master m where cb.contract_id = con.contract_id and cb.bp_category = 'GUARANTOR' and m.bp_id = CB.BP_ID) guarantor_id_n,
c.contract_number, (SELECT f.unit_name FROM fnd_org_unit f WHERE f.unit_id = p.unit_id) unit_id_n, p.employee_id, (select e.description from sys_user e where e.user_id = p.employee_id ) employee_id_n, (select hdt.description from hls_document_type hdt where hdt.business_type = c.business_type and hdt.document_category = 'PRJ_PROJECT' and hdt.document_type = 'PRJ_PROJECT' ) business_type_n, p.check_number,
p.write_company, (select fc.company_full_name from fnd_company fc where fc.company_id = p.write_company) write_company_n, p.check_type_locale, p.check_type_unlocale, p.check_type_other, p.check_user, c.contract_name, con.lease_start_date, con.lease_end_date, con.finance_amount, con.deposit_ratio, con.deposit, con.down_payment_ratio, con.down_payment, con.lease_charge_ratio, con.lease_charge, con.int_rate, ( select sum(nvl(c2.total_rental,0)-( select sum(nvl(cc2.received_amount,0)) from con_contract_cashflow cc2 where cc2.contract_id = c2.contract_id and cc2.cf_item IN (51, 1) and cc2.cf_status = 'RELEASE' )) from con_contract c2 left join prj_project p2 ON c2.project_id =p2.project_id where c2.tenant_id = c.tenant_id ) risk_exposure, ( select sum(nvl(pq2.first_rental,0)) from con_contract c2 left join prj_project p2 ON c2.project_id =p2.project_id left join prj_quotation pq2 on pq2.document_id = p2.project_id and pq2.source_document_category = 'PRJ_PROJECT' where c2.tenant_id = c.tenant_id ) first_rental, p.ANALYSE_CONCLUSION, p.invest_conclusion, p.next_check_matter, p.funds_mathch_scheme_flag, p.funds_situation_desc, p.risksignal_and_importantitem, p.manual_flag, (select max(pc.check_id) -- todo 修改为bp_id_tenant来判断 from prj_check pc,con_contract conc where PC.CONTRACT_ID = conc.PROJECT_ID AND conc.tenant_id = c.tenant_id and trunc(pc.check_date) < trunc(P.check_date) and pc.APPROVE_SUGGEST = 'APPROVED') last_check_id, (select hd.hd_id from prj_check_items_hd hd where hd.check_category='RISK' and hd.check_id=p.check_id) risk_hd_id, C.HOST_PROJECT_MANAGER, C.ASSIST_PROJECT_MANAGER, (SELECT sum(nvl(deposit,0)) FROM con_contract a,prj_project t WHERE t.tenant_id = c.tenant_id and a.project_id = t.project_id AND a.data_class = 'NORMAL' and a.contract_status in('INCEPT','PENDING') and a.tenant_id = c.tenant_id) deposit_merge, (SELECT sum(nvl(a.finance_amount,0)) FROM con_contract a,prj_project t WHERE t.tenant_id = c.tenant_id and a.project_id = t.project_id AND a.data_class = 'NORMAL' and a.contract_status in('INCEPT','PENDING') and a.tenant_id = c.tenant_id) finance_amount_merge FROM prj_check p, prj_project c left join con_contract con on con.project_id=c.project_id left join prj_quotation pq on pq.document_id = c.project_id and pq.source_document_category = 'PRJ_PROJECT' WHERE c.project_id = p.contract_id AND c.data_class = 'VIRTUAL_CON' AND c.data_type = 'NORMAL') t
1=1
and ( t.created_by = #{request.userId} or T.ASSIST_PROJECT_MANAGER = #{createdBy} or T.HOST_PROJECT_MANAGER = #{createdBy} or EXISTS (SELECT 1 FROM sys_user U LEFT JOIN SYS_USER_ALLOCATION UR ON UR.USER_ID = U.USER_ID LEFT JOIN SYS_ROLE_B R ON R.ROLE_ID = UR.ROLE_ID WHERE R.ROLE_CODE = 'ADMIN' and U.USER_ID = #{createdBy}))
AND t.bp_id = #{bpId}
AND exists (SELECT 1 FROM SYS_USER_ALLOCATION UR LEFT JOIN FND_EMPLOYEE_ASSIGNS ea ON ea.employee_assign_id = ur.employee_assign_id WHERE UR.USER_ID = t.employee_id and ea.employee_id = #{employeeId})
and to_char(t.check_date,'YYYY-MM-DD') >= #{checkDateFrom}
and to_char(t.check_date,'YYYY-MM-DD') <= #{checkDateTo}
and t.CHECK_ID = #{checkId}
and t.contract_number = #{contractNumber}
order by t.CHECK_ID desc

select nvl((select count(HACL.class_line_id) from HLS_ASSET_CLASS_LINE HACL,HLS_ASSET_CLASS_HEAD hac where t.MANUFACTURER_ID = hac.bp_id and t.year_n = hac.class_year and t.quarter_n = hac.CLASS_SEASON and HACL.class_head_id = hac.class_head_id), 0) CONTRACT_QUANTITY, --合同数量 nvl((select count(HACL.class_line_id) from HLS_ASSET_CLASS_LINE HACL,HLS_ASSET_CLASS_HEAD hac where t.MANUFACTURER_ID = hac.bp_id and t.year_n = hac.class_year and t.quarter_n = hac.CLASS_SEASON and HACL.class_head_id = hac.class_head_id and HACL.review_level in ('0', '1')), 0) normal_quantity, --正常数量 nvl((select sum(HACL.remaining_rent) from HLS_ASSET_CLASS_LINE HACL,HLS_ASSET_CLASS_HEAD hac where t.MANUFACTURER_ID = hac.bp_id and t.year_n = hac.class_year and t.quarter_n = hac.CLASS_SEASON and HACL.class_head_id = hac.class_head_id and HACL.review_level in ('0', '1')), 0) NORMAL_SURPLUS_RENTAL, --正常剩余租金 nvl((select count(HACL.class_line_id) from HLS_ASSET_CLASS_LINE HACL,HLS_ASSET_CLASS_HEAD hac where t.MANUFACTURER_ID = hac.bp_id and t.year_n = hac.class_year and t.quarter_n = hac.CLASS_SEASON and HACL.class_head_id = hac.class_head_id and HACL.review_level in ('2', '3')), 0) SPECIAL_MENTION_QUANTITY, --关注数量 nvl((select sum(HACL.remaining_rent) from HLS_ASSET_CLASS_LINE HACL,HLS_ASSET_CLASS_HEAD hac where t.MANUFACTURER_ID = hac.bp_id and t.year_n = hac.class_year and t.quarter_n = hac.CLASS_SEASON and HACL.class_head_id = hac.class_head_id and HACL.review_level in ('2', '3')), 0) SPECIAL_MENTION_SUR_REN, --关注剩余租金 nvl((select count(HACL.class_line_id) from HLS_ASSET_CLASS_LINE HACL,HLS_ASSET_CLASS_HEAD hac where t.MANUFACTURER_ID = hac.bp_id and t.year_n = hac.class_year and t.quarter_n = hac.CLASS_SEASON and HACL.class_head_id = hac.class_head_id and HACL.review_level in ('4')), 0) SUBSTANDARD_QUANTITY, --次级数量 nvl((select sum(HACL.remaining_rent) from HLS_ASSET_CLASS_LINE HACL,HLS_ASSET_CLASS_HEAD hac where t.MANUFACTURER_ID = hac.bp_id and t.year_n = hac.class_year and t.quarter_n = hac.CLASS_SEASON and HACL.class_head_id = hac.class_head_id and HACL.review_level in ('4')), 0) SUBSTANDARD_SURPLUS_RENTAL, --次级剩余租金 nvl((select count(HACL.class_line_id) from HLS_ASSET_CLASS_LINE HACL,HLS_ASSET_CLASS_HEAD hac where t.MANUFACTURER_ID = hac.bp_id and t.year_n = hac.class_year and t.quarter_n = hac.CLASS_SEASON and HACL.class_head_id = hac.class_head_id and HACL.review_level in ('5')), 0) DOUBTFUL_QUANTITY, --可疑数量 nvl((select sum(HACL.remaining_rent) from HLS_ASSET_CLASS_LINE HACL,HLS_ASSET_CLASS_HEAD hac where t.MANUFACTURER_ID = hac.bp_id and t.year_n = hac.class_year and t.quarter_n = hac.CLASS_SEASON and HACL.class_head_id = hac.class_head_id and HACL.review_level in ('5')), 0) DOUBTFUL_SURPLUS_RENTAL, --可疑剩余租金 nvl((select count(HACL.class_line_id) from HLS_ASSET_CLASS_LINE HACL,HLS_ASSET_CLASS_HEAD hac where t.MANUFACTURER_ID = hac.bp_id and t.year_n = hac.class_year and t.quarter_n = hac.CLASS_SEASON and HACL.class_head_id = hac.class_head_id and HACL.review_level = '6'), 0) LOSS_QUANTITY, --损失数量 nvl((select sum(HACL.remaining_rent) from HLS_ASSET_CLASS_LINE HACL,HLS_ASSET_CLASS_HEAD hac where t.MANUFACTURER_ID = hac.bp_id and t.year_n = hac.class_year and t.quarter_n = hac.CLASS_SEASON and HACL.class_head_id = hac.class_head_id and HACL.review_level = '6'), 0) LOSS_SURPLUS_RENTAL, --损失剩余租金 t.*, (select pc.check_date from prj_check pc where pc.check_id = t.last_check_id) last_check_date, (select scvb.meaning from sys_code_b scb, sys_code_value_b scvb,prj_check pc where scb.code_id = scvb.code_id and scvb.enabled_flag = 'Y' and scb.code = 'CHECK_TYPE' and scvb.value = pc.CHECK_TYPE and pc.check_id = t.last_check_id) last_check_type, (select pc.conclusion from prj_check pc where pc.check_id = t.last_check_id) last_conclusion, (select pc.next_check_matter from prj_check pc where pc.check_id = t.last_check_id) check_matter, (select pc.focus_matter from prj_check pc where pc.check_id = t.last_check_id) last_focus_matter, (select pc.correct_situation from prj_check pc where pc.check_id = t.last_check_id) last_correct_situation, (select pc.FIVE_CLASSIFICATION_RESULT from prj_check pc where pc.check_id = t.last_check_id) last_five_result, (select scvb.meaning from sys_code_b scb, sys_code_value_b scvb,prj_check pc where pc.check_id = t.last_check_id and scb.code_id = scvb.code_id and scvb.enabled_flag = 'Y' and scb.code = 'FIVE_CLASSIFICATION_RESULT' and scvb.value = pc.FIVE_CLASSIFICATION_RESULT) last_five_result_n from (select p.check_date, p.contract_id, p.process_instance_id, p.conclusion, p.exist_question, p.use_measure, p.policy_finance_situation, p.product_material_situation, p.product_environment_situation, p.office_environment_situation, p.product_time_situation, p.expand_invest, p.other_situation, p.CORRECT_SITUATION, p.product_conclusion five_classification_result, p.check_type, (select scvb.meaning from sys_code_b scb, sys_code_value_b scvb where scb.code_id = scvb.code_id and scvb.enabled_flag = 'Y' and scb.code = 'CHECK_TYPE' and scvb.value = p.CHECK_TYPE) CHECK_TYPE_N, (select scvb.meaning from sys_code_b scb, sys_code_value_b scvb where scb.code_id = scvb.code_id and scvb.enabled_flag = 'Y' and scb.code = 'FIVE_CLASSIFICATION_RESULT' and scvb.value = p.product_conclusion) five_classification_result_n, p.product_conclusion, (select scvb.meaning from sys_code_b scb, sys_code_value_b scvb where scb.code_id = scvb.code_id and scvb.enabled_flag = 'Y' and scb.code = 'FIVE_CLASSIFICATION_RESULT' and scvb.value = p.product_conclusion) product_conclusion_n, p.check_id, p.approve_suggest, (select scvb.meaning as value_name from sys_code_value_b scvb, sys_code_b scb where scb.code = 'HLS.WORK_FLOW_STATUS' and scb.code_id = scvb.code_id and scvb.enabled_flag = 'Y' and scvb.value= p.approve_suggest) approve_suggest_n, (select f.unit_name from fnd_org_unit f where f.unit_id = p.unit_id) unit_id_n, p.employee_id, (select e.description from sys_user e where e.user_id = p.employee_id ) employee_id_n, p.check_number, p.write_company, (select fc.company_full_name from fnd_company fc where fc.company_id = p.write_company) write_company_n, p.check_type_locale, p.check_type_unlocale, p.check_type_other, p.check_user, p.analyse_conclusion, p.invest_conclusion, p.next_check_matter, p.funds_mathch_scheme_flag, p.funds_situation_desc, p.risksignal_and_importantitem, p.manufacturer_id, p.manual_flag, (select hbm.bp_name from hls_bp_master hbm where hbm.bp_id = p.manufacturer_id) manufacturer_id_n, p.contract_cnt, p.contract_amt, to_char(add_months(p.check_date,-3),'Q') quarter_n, decode((to_char(add_months(p.check_date,-3),'Q')),4,to_char(p.check_date,'YYYY')-1,to_char(p.check_date,'YYYY')) year_n, decode(to_char(add_months(p.check_date,-3),'Q'),1,'第一季度',2,'第二季度',3,'第三季度',4,'第四季度') quarter, (select max(pc.check_id) from prj_check pc where PC.CONTRACT_ID = p.CONTRACT_ID and trunc(pc.check_date) < trunc(P.check_date) and pc.APPROVE_SUGGEST = 'APPROVED') last_check_id, (select hd.hd_id from prj_check_items_hd hd where hd.check_category='RISK' and hd.check_id=p.check_id) risk_hd_id from prj_check p where p.manufacturer_id is not null ) t
